import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class Verify{public static void main(String[] a)throws Exception{try(ZipFile m=new ZipFile(a[0]);ZipFile w=new ZipFile(a[1])){int[] count={0};Set<String> seen=new TreeSet<>();for(var en:Collections.list(m.entries()))if(en.getName().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(m.getInputStream(en)).accept(c,0);for(MethodNode method:c.methods)for(AbstractInsnNode i:method.instructions)if(i instanceof MethodInsnNode call&&call.owner.startsWith("com/armilp/ezweight/")){var target=w.getEntry(call.owner+".class");if(target==null)throw new AssertionError("Missing class "+call.owner);ClassNode t=new ClassNode();new ClassReader(w.getInputStream(target)).accept(t,0);boolean found=false;for(MethodNode d:t.methods)if(d.name.equals(call.name)&&d.desc.equals(call.desc)){if((d.access&Opcodes.ACC_PUBLIC)==0)throw new AssertionError("Not public");if(((d.access&Opcodes.ACC_STATIC)!=0)!=(call.getOpcode()==Opcodes.INVOKESTATIC))throw new AssertionError("Static mismatch");found=true;}if(!found)throw new AssertionError("Missing method "+call.name+call.desc);count[0]++;seen.add(call.owner+"."+call.name+call.desc);}}System.out.println("PASS "+count[0]+" binary call sites checked against supplied eZWeight v11");for(String s:seen)System.out.println(s);}}}
